use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let input_str = input.to_string();
    let mut parts: Vec<&str> = input_str.split('.').collect();
    let mut result = Vec::new();

    for part in parts {
        if let Ok(num) = part.parse::<i64>() {
            if num == 0 {
                result.push("0");
            } else if num < 0 {
                result.push("-");
            }
            result.push(format!("{num:04x}", num));
        } else {
            result.push("0");
        }
    }

    serde_json::Value::from(result)
}
